Rules.InvariantScript:
// =====================================================
// App.OnStart
// PULSE / WarRoom - Optimized global initialization
// =====================================================

// -----------------------------------------------------
// 1) Runtime / responsive layout
// -----------------------------------------------------
Set(varProjectSwitching, false);

Set(varW, App.Width);
Set(varH, App.Height);
Set(varRatio, varW / varH);

Set(varCompactMode, App.Height < 850);

Set(
    varBp,
    If(
        varW < 900,
        "S",
        If(varW < 1400, "M", "L")
    )
);

Set(
    varBpH,
    If(
        varH < 700,
        "S",
        If(varH < 900, "M", "L")
    )
);

Set(
    varFontBase,
    Switch(
        varBp,
        "S", 12,
        "M", 13,
        "L", 14,
        13
    )
);

Set(
    varH_Header,
    Switch(
        varBp,
        "S", 52,
        "M", 56,
        "L", 56,
        56
    )
);

Set(
    varH_Filters,
    Switch(
        varBp,
        "S", 104,
        "M", 88,
        "L", 88,
        88
    )
);

Set(varH_Status, 32);

Set(
    varPad,
    Switch(
        varBp,
        "S", 10,
        "M", 12,
        "L", 12,
        12
    )
);

Set(
    varGap,
    Switch(
        varBp,
        "S", 8,
        "M", 10,
        "L", 10,
        10
    )
);

// -----------------------------------------------------
// 2) Drawer responsive
// -----------------------------------------------------
Set(
    varDrawerMode,
    If(
        varW < 1100 || varH < 750,
        "Overlay",
        "Side"
    )
);

Set(
    varDrawerMaxW,
    Switch(
        varDrawerMode,
        "Side", 640,
        "Overlay", Min(900, RoundDown(varW * 0.92, 0)),
        640
    )
);

Set(
    varDrawerMaxH,
    Switch(
        varDrawerMode,
        "Side", varH - varH_Header - varPad * 2,
        "Overlay", Min(820, RoundDown(varH * 0.9, 0)),
        varH - varH_Header - varPad * 2
    )
);

// -----------------------------------------------------
// 3) Global visual tokens
// -----------------------------------------------------
Set(
    gblAppColors,
    {
        Primary: RGBA(95, 121, 151, 1),
        PrimaryDark: RGBA(75, 95, 120, 1),
        Background: RGBA(245, 247, 250, 1),
        Surface: RGBA(255, 255, 255, 1),
        Border: RGBA(0, 0, 0, 0.08),
        TextPrimary: RGBA(30, 30, 30, 1),
        TextSecondary: RGBA(100, 100, 100, 1),
        Success: RGBA(24, 130, 84, 1),
        Warning: RGBA(194, 120, 3, 1),
